using CatCafePreview.Standalone;
static partial class Program
{
 static void NarrativeChecks(string path,string output){Directory.CreateDirectory(output);var rules=Decode<CafeRules>(File.ReadAllText(path));rules.store_events.probability=0;var sim=new CafeSimulation(rules);var n=new CafeNarratives(sim);sim.Execute("player_begin",catId:"cat-mike");sim.Execute("player_step",choice:"direct");Assert(n.Rows.Count==1,"real action receipt");Assert(n.Rows[0].text.Contains("ねこじゃらし"),"teaser text");sim.Execute("player_step",choice:"switch",source:"pet");sim.Execute("player_step",choice:"direct");sim.Execute("player_step",choice:"pause");Assert(n.Rows.Count==4 && n.Rows[2].text.Contains("なで"),"pet and rest receipts");string id=sim.ActivePlayer.id,before=Encode(sim.State),text=n.Read(id);for(int i=0;i<30;i++)Assert(n.Read(id)==text,"stable reads");Assert(Encode(sim.State)==before,"reading consumes no resources");
 var store=new CafeSaveStore(output,s=>{s.narratives=n.Rows.ToArray();return ReplayEncode(s);},ReplayDecode,sim.Validate);store.Save(1,sim.State);var save=store.Load(1);CafeNarratives.Validate(save);sim.Restore(save.state);n.Restore(save.narratives);Assert(n.Read(id)==text,"disk reload preserves prose");sim.Execute("player_finish");sim.Execute("player_begin",catId:"cat-mike");Assert(n.Read(sim.ActivePlayer.id)!=text,"separate player sets");sim.Execute("player_finish");sim.Execute("set_shifts",working:new[]{"cat-mike"});sim.Execute("start_business");for(int i=0;i<rules.opening_ticks && sim.State.phase=="open";i++)sim.Execute("advance_business");Assert(n.Rows.Any(r=>r.customer_id!="player"),"automatic service captured while closed UI");var services=n.Rows.Where(r=>r.customer_id!="player").GroupBy(r=>r.session).ToArray();Assert(services.Length>=2,"same seat serves successive visitors");Assert(services.All(g=>g.Select(r=>r.customer_id).Distinct().Count()==1),"customers isolated");foreach(var g in services)Assert(n.Read(g.Key).Contains(g.Last().text),"latest service");
 store.Save(2,sim.State);var serviceSave=store.Load(2);string serviceText=n.Read(services[0].Key);sim.Restore(serviceSave.state);n.Restore(serviceSave.narratives);Assert(n.Read(services[0].Key)==serviceText,"completed service prose survives reload");Assert(n.Seat(null).Contains("空席"),"empty seat excludes old customer");var old=store.Load(1);old.narratives=null;sim.Restore(old.state);n.Restore(old.narratives);Assert(!n.Read(sim.ActivePlayer.id).Contains("プレイヤー「"),"old save does not invent text");sim.Execute("player_step",choice:"direct");Assert(n.Rows.Single().turn==5,"old partial save continues at actual turn");
 var coverage=new HashSet<string>(); foreach(string mode in new[]{"teaser","pet"})foreach(string action in new[]{"direct","adapt","intense","feint"})foreach(double stamina in new[]{100.0,10.0}){var e=new CafeExchange{cat_id="cat-mike",customer_id="player",mode=mode,remaining=20,stamina=stamina};if(!rules.types.Single(t=>t.id==mode).actions.Contains(action))continue;sim.StepExchange(e,sim.Definition("cat-mike"),action);coverage.Add(e.previous_reaction);var row=CafeNarratives.Compose("プレイヤー",mode,action,e.previous_reaction,stamina,e.stamina);Assert(row.reaction==e.previous_reaction,"actual reaction retained");if(e.previous_reaction=="turn_away")Assert(row.text.Contains("顔を背け"),"refusal prose");if(e.previous_reaction=="listless")Assert(row.text.Contains("休む時間"),"low stamina prose");if(e.previous_reaction=="favorable" || e.previous_reaction=="enthusiastic")Assert(row.text.Contains("前足") || row.text.Contains("目を細め"),"positive prose");}
 var refusalProfile=Decode<CatDefinition>(Encode(sim.Definition("cat-mike")));refusalProfile.type_preferences[0]=0;var refusal=new CafeExchange{mode="teaser",remaining=20,stamina=100};sim.StepExchange(refusal,refusalProfile,"direct");coverage.Add(refusal.previous_reaction);Assert(CafeNarratives.Compose("プレイヤー","teaser","direct",refusal.previous_reaction,100,refusal.stamina).text.Contains("顔を背け"),"refusal boundary fixture");
 Assert(coverage.Contains("turn_away") && coverage.Contains("listless") && (coverage.Contains("favorable") || coverage.Contains("enthusiastic")),"required reaction coverage");
 File.WriteAllText(Path.Combine(output,"summary.txt"),assertions+" assertions passed\n"+text);Console.WriteLine(assertions+" narrative assertions passed");
 }
 static void NarrativeResume(string rulesPath,string output){var rules=Decode<CafeRules>(File.ReadAllText(rulesPath));rules.store_events.probability=0;var sim=new CafeSimulation(rules);var store=new CafeSaveStore(output,ReplayEncode,ReplayDecode,sim.Validate);var save=store.Load(1);CafeNarratives.Validate(save);sim.Restore(save.state);var n=new CafeNarratives(sim);n.Restore(save.narratives);string text=n.Read(sim.ActivePlayer.id);Assert(File.ReadAllText(Path.Combine(output,"summary.txt")).Contains(text),"separate process preserves prose");string before=Encode(sim.State);n.Read(sim.ActivePlayer.id);Assert(before==Encode(sim.State),"separate process read-only");Console.WriteLine(assertions+" resume assertions passed");}

}


